SELECT s1.`c0` AS `x` FROM (SELECT s2.`c0` AS `c0`, s2.`o` AS `o` FROM (SELECT s3.`c2` AS `c0`, s3.`o` AS `o` FROM (SELECT s4.`c0` AS `c0`, s4.`c1` AS `c1`, s4.`c1` AS `c2`, s4.`o` AS `o` FROM (SELECT s5.`c0` AS `c0`, s5.`c1` AS `c1`, s5.`o` AS `o` FROM (SELECT v.`c0` AS `c0`, v.`c1` AS `c1`, v.`o` AS `o` FROM (VALUES (CAST(1 AS BIGINT), CAST(10 AS BIGINT), CAST(0 AS BIGINT)), (CAST(1 AS BIGINT), CAST(30 AS BIGINT), CAST(1 AS BIGINT)), (CAST(2 AS BIGINT), CAST(20 AS BIGINT), CAST(2 AS BIGINT)), (CAST(NULL AS BIGINT), CAST(40 AS BIGINT), CAST(3 AS BIGINT)), (CAST(2 AS BIGINT), CAST(NULL AS BIGINT), CAST(4 AS BIGINT)), (CAST(1 AS BIGINT), CAST(5 AS BIGINT), CAST(5 AS BIGINT))) AS v(`c0`, `c1`, `o`)) AS s5 WHERE ((NOT (s5.`c0` IS NULL)) IS TRUE)) AS s4) AS s3) AS s2 ORDER BY s2.`o` ASC NULLS LAST LIMIT 2 OFFSET 1) AS s1 ORDER BY s1.`o` ASC NULLS LAST
